// acl/index.js - the domain imports only from here
import { LegacyReceipt } from "./legacy-schema.js";
import { toLegacy, toReceipt } from "./mapping.js";

export async function placeOrder(order) {                 // domain-shaped API
  const res = await fetch(`${BASE}/orders`, {
    method: "POST", body: JSON.stringify(toLegacy(order)),  // foreign shape stays inside
  });
  if (!res.ok) throw new OrderRejected(`legacy ${res.status}`);
  return toReceipt(LegacyReceipt.parse(await res.json()));  // validate at the seam
}
